// Parse AI output and return [{url, source}]
let results = [];

for (const item of items) {
  let data = item.json.output ?? item.json;

  // Clean markdown fences if present
  if (typeof data === "string") {
    let cleaned = data
      .replace(/```json\s*/gi, "")
      .replace(/```\s*/g, "")
      .trim();

    try {
      data = JSON.parse(cleaned);
    } catch (e) {
      // If it's just a raw URL string, wrap it
      if (/^https?:\/\//i.test(cleaned)) {
        results.push({ url: cleaned, source: "unknown" });
      }
      continue;
    }
  }

  // If we got an array of objects
  if (Array.isArray(data)) {
    data.forEach(entry => {
      if (entry && typeof entry === "object" && entry.url) {
        const normalized = normalizeUrl(entry.url);
        if (normalized) {
          results.push({
            url: normalized,
            source: entry.source ?? "unknown"
          });
        }
      }
    });
  }

  // If it's a single object
  if (data && typeof data === "object" && !Array.isArray(data) && data.url) {
    const normalized = normalizeUrl(data.url);
    if (normalized) {
      results.push({
        url: normalized,
        source: data.source ?? "unknown"
      });
    }
  }
}

// Helper: normalize URL - strip query params, hash, trailing slash
function normalizeUrl(url) {
  try {
    let u = new URL(url);

    // Remove tracking parameters
    const trackingParams = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'ref', 'source', 'fbclid', 'gclid'];
    trackingParams.forEach(param => u.searchParams.delete(param));

    // If no other params remain, clear search entirely
    if (u.searchParams.toString() === '') {
      u.search = '';
    }

    u.hash = "";
    return u.href.replace(/\/$/, "");
  } catch (e) {
    return null;
  }
}

// Deduplicate by URL
const seen = new Set();
results = results.filter(r => {
  if (seen.has(r.url)) return false;
  seen.add(r.url);
  return true;
});

return results.map(r => ({ json: r }));

const inputData = $input.first().json;
let baseUrl = inputData.url || inputData.website_url || '';

if (!baseUrl) {
  throw new Error("No URL provided");
}

baseUrl = baseUrl.replace(/\/$/, '');

let domain = '';
if (baseUrl.includes('://')) {
  const parts = baseUrl.split('/');
  domain = parts[0] + '//' + parts[2];
} else {
  domain = 'https://' + baseUrl;
}

const urls = [
  `${domain}/robots.txt`,
  `${domain}/sitemap.xml`,
  `${domain}/sitemap_index.xml`,
  `${domain}/sitemap-index.xml`,
  `${domain}/sitemap1.xml`,
  `${domain}/sitemap/sitemap.xml`,
  `${domain}/sitemaps/sitemap.xml`
];

return urls.map(url => ({ sitemap_url: url }));

const allUrls = [];

$input.all().forEach(item => {
  const content = item.json.data || '';

  const robotMatches = [...content.matchAll(/Sitemap:\s*(\S+)/gi)];
  robotMatches.forEach(match => {
    allUrls.push(match[1]);
  });

  const locMatches = [...content.matchAll(/<loc>\s*(.*?)\s*<\/loc>/gi)];
  locMatches.forEach(match => {
    allUrls.push(match[1]);
  });
});

const uniqueUrls = [...new Set(allUrls)];

return uniqueUrls.map(url => ({ json: { sitemap_url: url }}));

const urls = new Set();

$input.all().forEach(item => {
  const content = item.json.data || '';

  const xmlMatches = [...content.matchAll(/<loc>(.*?)<\/loc>/gi)];
  xmlMatches.forEach(match => {
    const url = match[1].trim();
    urls.add(url);
  });

  const htmlMatches = [...content.matchAll(/<a\s[^>]*href=["']([^"']+)["']/gi)];
  htmlMatches.forEach(match => {
    const url = match[1].trim();
    if (url.startsWith('/') || url.startsWith('http')) {
      urls.add(url);
    }
  });
});

if (urls.size === 0) {
  return [{ json: { message: "No URLs found in XML or HTML content" }}];
}

return Array.from(urls).map(url => ({
  json: { page_url: url }
}));
